import{_ as n,l as s,o as e,c as l,v as t,p as r,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"连续对离散视觉 token","description":"","frontmatter":{"title":"连续对离散视觉 token","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continuous-vs-discrete-vision-tokens.md","filePath":"llm/continuous-vs-discrete-vision-tokens.md","lastUpdated":1789023840000}'),h={name:"llm/continuous-vs-discrete-vision-tokens.md"};function _(m,a,u,E,A,f){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="连续对离散视觉-token" tabindex="-1">连续对离散视觉 token <a class="header-anchor" href="#连续对离散视觉-token" aria-label="Permalink to &quot;连续对离散视觉 token&quot;">​</a></h1><div class="epigraph"><p>理解型 VLM 多用连续 patch 投影进 LLM；生成型系统常用离散码接自回归，或连续潜变量接扩散。接口选错，后半段再强也补不回。</p><footer>—— 对照 LLaVA 连续视觉 token 与 VQ / 潜空间扩散两条生成路</footer></div><p><a href="/llm/fsq-lfq">上一课</a>用固定网格或无查找编码避免码本崩溃；词表是设计量，ID 邻域不等于语义邻域。缺口是任务轴：绑定与 OCR 对连续早融合友好，似然生成对离散友好，高保真采样对连续扩散友好。主干 <a href="/llm/llava-projector">LLaVA 投影器</a> 走连续 ViT 隐状态；前三课把离散量化写清。本课把选择收成这一轴。不重讲 FSQ 的量化格。后课原生分辨率 ViT 默认已经读完：连续 token 的个数随分辨率涨。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>连续：ViT 输出 \\(H_v\\in\\mathbb{R}^{N\\times d}\\)，线性或 MLP 投进 LLM 词嵌入空间，梯度从语言损失直达视觉编码器。无码本崩溃，细字靠 \\(N\\) 与分辨率。不能在视觉维上做标准 softmax 词表，生成图像要另接扩散头或连续回归。</p><p>离散：下标序列，LLM 可以统一词表生成图与文，但量化丢信息，文档与定位吃亏。混合系统（理解连续、生成离散）要两套视觉前缀，训练更复杂，后课 Janus / Show-o 再写。</p><p><span class="marginnote">「视觉 token」一词在文献里混用。写报告时声明是连续向量还是码本 ID。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>理解 / 对话 / OCR：连续 + 早融合，见融合课。像素级生成：离散 AR 或潜空间扩散（后一单元）。统一模型必须显式选：共享词表、双头、或 Transfusion 式混合目标。评测不要用图文检索余弦去选对话 VLM 的离散码本。</p>',9)),(e(),r(p,null,{default:o(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20C%5B%22%E8%BF%9E%E7%BB%AD%20patch%20%E5%90%91%E9%87%8F%22%5D%0A%20%20PIX%20--%3E%20D%5B%22%E7%A6%BB%E6%95%A3%E7%A0%81%20ID%22%5D%0A%20%20C%20--%3E%20VLM%5B%22%E5%AF%B9%E8%AF%9D%20%2F%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20D%20--%3E%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E7%94%9F%E6%88%90%22%5D%0A%20%20C%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%20%2F%20%E6%B5%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>语言损失对连续 \\(H_v\\) 提供稠密梯度，对离散 ID 只提供词表上的交叉熵，中间的解码器是另一套参数。因此理解任务微调 ViT 很有效，微调 VQ 编码器对问答帮助有限——瓶颈在码。生成任务相反：没有离散词表就没有统一的 next-token 目标。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定唯一赢家。下一课在连续路上补分辨率：固定 224 画布是理解侧的第一瓶颈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续视觉 token 服务绑定与 OCR；离散码服务统一似然生成。</li><li>梯度路径不同，微调对象不同。</li><li>名词必须声明连续还是 ID。</li><li>出处：LLaVA 连续投影；VQGAN / LDM 生成接口。</li></ul>',6))])}const V=n(h,[["render",_]]);export{D as __pageData,V as default};
